#include <cstdio>
#include <cstring>
#include <cmath>
#include <cstdlib>
#include <vector>
#include <string>
#include <algorithm>
#include <queue>
#include <stack>
#include <deque>
#include <map>
#include <set>
#include <unordered_map>
#include <unordered_set>
#include <functional>
#include <numeric>
#include <sstream>
#include <iostream>
using namespace std;
int main(){string s;getline(cin,s);
int n=s.size();
if(n==0){printf("0\n");return 0;}
vector<vector<int>>dp(n,vector<int>(n,0));
for(int i=0;i<n;++i)dp[i][i]=1;
for(int len=2;len<=n;++len)for(int i=0;i+len-1<n;++i){
int j=i+len-1;
if(s[i]==s[j])dp[i][j]=(len>2?dp[i+1][j-1]:0)+2;
else dp[i][j]=max(dp[i+1][j],dp[i][j-1]);}
printf("%d\n",dp[0][n-1]);return 0;}

